import re

def extract_bid_price(text, coupon, maturity):
    """Extract bid price from the table row"""
    # Find rows with the right coupon and maturity
    pattern = r'<tr><td>[^<]+</td><td>' + re.escape(coupon) + r'</td><td>[^<]*</td><td>' + re.escape(maturity) + r'[^<]*</td><td>(\d+\.\d+)</td>'
    match = re.search(pattern, text)
    if match:
        return match.group(1)
    return None

# Test each year
